function outerAct(){choose('結交哪位外臣？',S.cr.slice().sort((a,b)=>b.gd-a.gd).slice(0,24).map(f=>({l:`${f.role}${f.n}（${GRN[f.gd]}・${FAC[f.fac]}${f.fac===S.me.fac?'・母家一派':''}）`,f(){choose(`如何與${f.n}往來？`,[
{l:'託母家送厚禮（耗銀30）',f(){if(!pay(30))return L('銀兩不足。');f.lo=cl(f.lo+8);S.fp[f.fac]=cl(S.fp[f.fac]+2);famBoost(S.me,R(2,5),0);L(`${f.role}${f.n}收下厚禮，答應日後關照你的母家。`)}},
{l:'請他在朝上為你說話',f(){if(f.lo>=50&&P(.6)){S.me.favor+=6;S.me.ally+=3;L(`${f.n}在朝上替你美言幾句，皇上對你多了幾分留意。`)}else L(`${f.n}含糊其辭，並未表態。`)}},
{l:'打探朝局消息',f(){S.me.scheme+=2;const o=pk(S.cr.filter(x=>x!==f));L(`你從${f.n}口中得知：${o?`${o.role}${o.n}近來頗有失勢之兆。`:'朝中暫無大事。'}`);if(P(.18)){S.me.favor-=8;L('後宮私通外臣之事被人察覺，皇上很不高興。')}}}])}})));return 1}
