const kb2=(l,v)=>`<div class=r><span>${l}</span><i><b style="width:${Math.max(0,Math.min(100,v))}%"></b></i><em>${v|0}</em></div>`;
const FQ={};
function fbar(k,chips,ph){const f=FQ[k]||{q:'',c:''};return`<div class=fbar data-fk="${k}"><input type=search placeholder="${ph||'搜尋'}" value="${f.q.replace(/"/g,'')}" oninput="fq('${k}','q',this.value)"><div class=chips>${chips.map(c=>`<button class="chip${f.c===c?' on':''}" onclick="fqc('${k}','${c}')">${c}</button>`).join('')}</div></div>`}
