function fq(k,p,v){(FQ[k]=FQ[k]||{q:'',c:''})[p]=v;fApply()}
function fqc(k,c){const f=(FQ[k]=FQ[k]||{q:'',c:''});f.c=f.c===c?'':c;document.querySelectorAll(`[data-fk="${k}"] .chip`).forEach(b=>b.classList.toggle('on',b.textContent===f.c));fApply()}
