function rowT(n){const me=n===S.me;return `${n.name||n.n} ${me?'你 主角':''} ${n.st||RK[n.rank]} ${me&&S.reg?S.reg.title:RKD(n)} ${FAC[n.fac]} ${n.rank>=5?'高位':n.rank>=3?'中位':'低位'} ${n.preg?'有孕':''} ${n.kids.length?'有子嗣':''} ${n.kf&&kfOf(n)?'官家之女 '+kfOf(n).role+kfOf(n).n:''}`}
