/* ===== v35 匿名遊玩回報與後台統計（需在 Claude 頁面內，並由作者分享為可互動） ===== */
let EDITOR=0;
const hasCl=()=>typeof claude!=='undefined'&&claude&&typeof claude.use==='function';
function runRec(){const m=S.me,s=scoreOf();return{ts:Date.now(),end:S.over.t,score:s,tier:SCT(s),years:Math.floor(S.t/12),origin:GS[G][0],talent:TS[m.g][0],diff:DFN[S.diff||0][0],goal:GOALS[S.goal||0][0],gd:S.gdone?1:0,rank:RK[m.rank],reg:S.reg?1:0,kids:m.kids.length,ach:ACH().size,silver:m.silver|0}}
async function reportRun(){if(!S||S.rep||!S.over||!hasCl())return;S.rep=1;try{const db=await claude.use('db'),u=await claude.use('user');if(!db||!u)return;const id=await u.id();if(!id)return;const ref=db.doc('runs/'+id),sn=await ref.get(),g=(sn.exists&&sn.data().games)||[];g.push(runRec());await ref.set({games:g.slice(-80),last:Date.now()})}catch(e){console.log('report',e&&e.code||e)}}
const _ov0=over;over=function(t,x){const r=_ov0.apply(this,arguments);try{if(S&&S.over)reportRun()}catch(e){}return r};
if(hasCl())claude.use('user').then(u=>{if(u&&u.canEdit&&u.canEdit()){EDITOR=1;if(S&&TAB==5)render()}}).catch(()=>{});
function statsCard(){return EDITOR?`<div class=cd><h3>後台統計（僅作者可見）</h3><div class=m>匯總所有玩家結局時匿名回報的資料。</div><p><button class=s onclick="loadStats()">載入玩家統計</button></p><div id=statsBox class=m></div></div>`:''}
async function loadStats(){const box=document.getElementById('statsBox');if(!box)return;box.textContent='讀取中…';try{const db=await claude.use('db'),sn=await db.collection('runs').get(),all=[];let players=sn.size;sn.docs.forEach(d=>{((d.data()||{}).games||[]).forEach(g=>all.push(g))});
if(!all.length){box.textContent='還沒有玩家回報的資料。';return}
const cnt=(f)=>{const o={};all.forEach(g=>{const k=f(g);o[k]=(o[k]||0)+1});return Object.entries(o).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`${k} ${v}（${Math.round(v*100/all.length)}%）`).join('<br>')};
const avg=f=>(all.reduce((s,g)=>s+(f(g)||0),0)/all.length).toFixed(1);
box.innerHTML=`玩家 ${players} 人・共 ${all.length} 局<br>平均評分 ${avg(g=>g.score)}・平均存活 ${avg(g=>g.years)} 年・平均子嗣 ${avg(g=>g.kids)}・平均成就 ${avg(g=>g.ach)}<br>臨朝稱制 ${all.filter(g=>g.reg).length} 局・目標達成 ${all.filter(g=>g.gd).length} 局<hr><b>結局分布</b><br>${cnt(g=>g.end)}<hr><b>出身</b><br>${cnt(g=>g.origin)}<hr><b>難度</b><br>${cnt(g=>g.diff)}<hr><b>人生目標</b><br>${cnt(g=>g.goal)}<hr><b>天賦</b><br>${cnt(g=>g.talent)}<hr><b>評價等級</b><br>${cnt(g=>g.tier)}<hr><b>最高位份</b><br>${cnt(g=>g.rank)}`}catch(e){box.textContent='讀取失敗：'+(e&&e.message||e)}}
/* ===== v36 優化：自動存檔・頭像輕量化・通知精簡・新手說明 ===== */
