function plotCard(){const p=S.pl;if(!p)return'';return`<div class=cd data-open=1><h3>主線劇情</h3><div class=m>「${PLN[p.id]}」${p.done?'・已落幕':`・第${Math.min(p.st+1,3)}幕 / 共3幕`}</div></div>`}
/* 主流程 */
const _mQ=mend;mend=function(){const r=_mQ.apply(this,arguments);try{if(!S||!S.me||S.over||S.reg)return r;const m=S.me,mo=S.t%12,ev=[];S.cn=S.cn||[];const due=S.cn.filter(c=>c.at<=S.t);S.cn=S.cn.filter(c=>c.at>S.t);due.forEach(c=>{if(CHN[c.k])ev.push(CHN[c.k]())});
if(S.epi&&S.epi.m>0){if(!S.epi.p)m.hp=Math.max(3,m.hp-R(1,3));S.npcs.forEach(n=>{if(!n.st&&!S.epi.p)n.hp=Math.max(5,n.hp-R(0,2))});S.epi.m--;if(S.epi.m<=0){S.epi=null;L('宮中疫情漸漸平息。')}}
if(S.t>0&&FEST[mo])ev.push(FEST[mo]());else if(mo%3==1&&P(.45))ev.push(SEV[seasOf(S.t)]());
if(!S.epi&&S.t>24&&P(.012))ev.push(EPIE());
plRun(ev);
if(ev.length){ev.slice(0,3).forEach(x=>S.q.push(x));if(!S.ev&&!S.ch&&!S.scn)next();else render()}}catch(e){console.log('plus2',e)}return r};
const _gcQ=goalChip;goalChip=function(){let s='';try{s=S.reg?'':plotCard()}catch(e){}return _gcQ.apply(this,arguments)+s};
/* 人物小傳 */
