function dKey(){const d=new Date(),p=n=>String(n).padStart(2,'0');return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())}
function mulb(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function hashS(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function dailyStart(){const key=dKey(),rnd=mulb(hashS('hg'+key)),orig=Math.random;DLY=1;Math.random=rnd;try{G=Math.floor(rnd()*GS.length);T=Math.floor(rnd()*TS.length);AT=null;GOAL=0;DIFF=1;N=N||'沈氏';start();S.dly=key;S.dlyOk=1}finally{Math.random=orig;DLY=0}render()}
