function ap(s){if(!s)return;const m=S.me;s.split(',').forEach(x=>{const q=x.split(':'),k=q[0],d=+q[1];if(k=='favor')m.favor=Math.max(0,m.favor+d);else if(k=='ally')m.ally+=d;else if(k=='scheme')m.scheme+=d;else if(k=='silver')m.silver=Math.max(0,m.silver+d);else if(k=='hp')m.hp=Math.max(3,Math.min(100,m.hp+d));else if(k=='dw')m.dw=cl(m.dw+d);else if(k=='emp')m.emp+=d;else if(k=='scand')m.scand=Math.max(0,(m.scand||0)+d);else if(k=='fam')m.fam.forEach(f=>f.pw=cl(f.pw+d));else if(k=='kb')m.kids.forEach(z=>z.bond=cl(z.bond+d));else if(k=='ev'){const a=ids();if(a.length){const i=a[R(0,a.length-1)];S.evid[i]=(S.evid[i]||0)+1}}else if(k=='mood')S.mood=cl(S.mood+d)})}
function fxo(sp){if(sp.c&&!pay(sp.c))return{t:sp.nt||'銀兩不足，你什麼也做不了。',ok:0};const pr=typeof sp.pr=='function'?sp.pr():sp.pr,ok=pr==null||P(pr);ap(ok?sp.e:sp.be);return{t:ok?sp.t:(sp.bt||sp.t),ok:ok?1:0}}
const O=(lab,e,t,x)=>[lab,Object.assign({e,t},x||{})];
function plAdv(p,d,end,res,sc){p.st++;p.nx=S.t+d;if(end||p.st>=PLT[p.id].length){p.done=1;S.pf=S.pf||[];S.pf.push({id:p.id,res:res||'落幕',s:sc||0});msPush('主線「'+PLN[p.id]+'」：'+(res||'落幕'));try{const o=lgGet();o.ln=o.ln||[];if(!o.ln.includes(p.id)){o.ln.push(p.id);lgSet(o)}}catch(e){}}}
function EV(p,t,opts){return{t,o:opts.map(([lab,sp])=>[lab,()=>{const r=fxo(sp);if(r.ok||sp.c){if(sp.f)Object.assign(p.f,sp.f)}if(!r.ok&&sp.bf)Object.assign(p.f,sp.bf);if(r.ok&&sp.ov&&!(sp.c&&!r.ok))over(sp.ov[0],sp.ov[1]);if(!r.ok&&sp.bov)over(sp.bov[0],sp.bov[1]);const d=sp.d?R(sp.d[0],sp.d[1]):R(10,16);plAdv(p,d,sp.end,r.ok?sp.res:(sp.bres||sp.res),r.ok?sp.sc:(sp.bsc!=null?sp.bsc:sp.sc));return r.t}])}}
