function plNew(id,old){return{id,st:0,nx:S.t+(old?R(8,16):R(14,26)),f:{},nm:MN[R(0,MN.length-1)],k:null}}
function plOrg(){const n=(GS[G]||[''])[0]||'';return/公主/.test(n)?'envoy':n=='罪臣之女'?'revenge':n=='宮女出身'?'maid':/商賈|鹽商/.test(n)?'trade':/評彈|書香/.test(n)?'art':null}
function plPick(old){const g=['love','plot','heir','edict'];return plNew((!old&&plOrg())||g[R(0,3)],old)}
function plRun(ev){if(!S.pl)return;const ls=[S.pl];if(S.pl2)ls.push(S.pl2);else if(!S.pl2d&&(S.pl.done||S.t>=84)){const all=['love','plot','heir','edict'].concat(plOrg()?[plOrg()]:[]).filter(x=>x!==S.pl.id);S.pl2=plNew(all[R(0,all.length-1)],0);S.pl2d=1;S.pl2.nx=S.t+R(6,12);ls.push(S.pl2)}
ls.forEach(p=>{if(p.done||S.t<p.nx||!PLT[p.id]||!PLT[p.id][p.st])return;const e=PLT[p.id][p.st](p);if(e)ev.push(e);else p.nx=S.t+3})}
function plotCard(){const a=[S.pl,S.pl2].filter(Boolean);if(!a.length)return'';return`<div class=cd data-open=1><h3>主線劇情</h3>`+a.map(p=>`<div class=m>「${PLN[p.id]}」${p.done?'・已落幕':`・第${Math.min(p.st+1,PLT[p.id].length)}幕 / 共${PLT[p.id].length}幕`}</div>`).join('')+'</div>'}
