function castTick(ev){if(!S.cast)return;const a=Object.values(S.cast).filter(c=>c.st==='在世'&&S.t-c.lt>=8);if(!a.length||!P(.12))return;const c=a[R(0,a.length-1)],k=Object.keys(S.cast).find(x=>S.cast[x]===c);c.lt=S.t;ev.push(CAE[k](c))}
function castPanel(){if(S.reg||!S.cast)return'';return`<div class=cd data-open=0><h3>身邊人物</h3><div class=m>這些人會一再出現在你的故事裡，你與他們的往來會決定他們的立場。</div>`+Object.values(S.cast).map(c=>`<div class=k>${c.n}（${c.r}）・${c.st==='在世'?aw(c.af)+' '+(c.af|0):c.st}</div>`).join('')+'</div>'}
const _rhS=rosterHTML;rosterHTML=function(){let a='';try{a=castPanel()}catch(e){}return a+_rhS.apply(this,arguments)};
